{
    private readonly Transport _t;

    internal SurveysApi(Transport transport)
    {
        _t = transport;
    }

    /// <summary>Lists surveys, newest change first.</summary>
    /// <remarks>Scope surveys:read. Pages on a cursor: pass nextCursor as cursor until it is null.</remarks>
    public Task<PublicSurveyPage> ListAsync(string? status = null, int? limit = null, string? cursor = null, CancellationToken cancellationToken = default) =>
        _t.SendAsync<PublicSurveyPage>(HttpMethod.Get, $"/api/v1/surveys", [("status", status), ("limit", limit), ("cursor", cursor)], null, null, cancellationToken);

    /// <summary>Every item of ListAsync, page after page.</summary>
    public IAsyncEnumerable<PublicSurveyItem> ListAllAsync(string? status = null, int? limit = null, CancellationToken cancellationToken = default) =>
        Transport.ByCursorAsync(cursor => ListAsync(status, limit, cursor, cancellationToken: cancellationToken), page => page.Items, page => page.NextCursor, cancellationToken);

    /// <summary>Reads one survey, with its published versions and links.</summary>
    /// <remarks>Scope surveys:read.</remarks>
    public Task<PublicSurvey> GetAsync(Guid surveyId, CancellationToken cancellationToken = default) =>
        _t.SendAsync<PublicSurvey>(HttpMethod.Get, $"/api/v1/surveys/{surveyId}", [], null, null, cancellationToken);
}

